using Microsoft.Data.SqlClient;using Microsoft.EntityFrameworkCore;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Application.Features.Printing;
namespace WhatsBiz.Infrastructure.Persistence;
public sealed class PrintRepository(ApplicationDbContext db):IPrintRepository{
public async Task<IReadOnlyCollection<PrintTemplateDto>>Templates(string? type,CancellationToken token){var list=new List<PrintTemplateDto>();await using var c=(SqlConnection)db.Database.GetDbConnection();await c.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="SELECT DocumentTemplateId,TemplateCode,TemplateName,DocumentType,PaperType,IsDefault,HtmlTemplate FROM printing.DocumentTemplates WHERE IsActive=1 AND (@type IS NULL OR DocumentType=@type) ORDER BY DocumentType,IsDefault DESC,TemplateName";q.Parameters.AddWithValue("@type",(object?)type??DBNull.Value);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetBoolean(5),r.GetString(6)));return list;}
public async Task<IReadOnlyCollection<PrinterDto>>Printers(CancellationToken token){var list=new List<PrinterDto>();await using var c=(SqlConnection)db.Database.GetDbConnection();await c.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="SELECT PrinterConfigurationId,PrinterName,DisplayName,PrinterType,PaperSize,DocumentType,IsDefault,AutoCut,IsActive FROM printing.PrinterConfigurations ORDER BY IsDefault DESC,DisplayName";await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.GetBoolean(6),r.GetBoolean(7),r.GetBoolean(8)));return list;}
public async Task SavePrinter(PrinterInput x,CancellationToken token){await using var c=(SqlConnection)db.Database.GetDbConnection();await c.OpenAsync(token);await using var tx=await c.BeginTransactionAsync(token);if(x.IsDefault){await using var clear=c.CreateCommand();clear.Transaction=(SqlTransaction)tx;clear.CommandText="UPDATE printing.PrinterConfigurations SET IsDefault=0 WHERE PrinterType=@type";clear.Parameters.AddWithValue("@type",x.PrinterType);await clear.ExecuteNonQueryAsync(token);}await using var q=c.CreateCommand();q.Transaction=(SqlTransaction)tx;q.CommandText=x.Id is null?"INSERT printing.PrinterConfigurations(PrinterName,DisplayName,PrinterType,PaperSize,DocumentType,IsDefault,AutoCut,IsActive) VALUES(@name,@display,@type,@paper,@document,@default,@cut,@active)":"UPDATE printing.PrinterConfigurations SET PrinterName=@name,DisplayName=@display,PrinterType=@type,PaperSize=@paper,DocumentType=@document,IsDefault=@default,AutoCut=@cut,IsActive=@active WHERE PrinterConfigurationId=@id";q.Parameters.AddWithValue("@id",(object?)x.Id??DBNull.Value);q.Parameters.AddWithValue("@name",x.PrinterName);q.Parameters.AddWithValue("@display",x.DisplayName);q.Parameters.AddWithValue("@type",x.PrinterType);q.Parameters.AddWithValue("@paper",x.PaperSize);q.Parameters.AddWithValue("@document",(object?)x.DocumentType??DBNull.Value);q.Parameters.AddWithValue("@default",x.IsDefault);q.Parameters.AddWithValue("@cut",x.AutoCut);q.Parameters.AddWithValue("@active",x.IsActive);await q.ExecuteNonQueryAsync(token);await tx.CommitAsync(token);}}
